SELECT f.subject_id, f.hadm_id, f.gender, f.anchor_age, f.anchor_year, f.anchor_year_group, f.icd_code, f.description, f.drug_type, f.drug, f.formulary_drug_cd, f.gsn, f.ndc, f.prod_strength, f.form_rx, f.dose_val_rx, f.dose_unit_rx, f.form_val_disp, f.form_unit_disp, f.doses_per_24_hrs, f.route, f.frequency, f.disp_sched, f.infusion_type, f.sliding_scale, f.lockout_interval, f.basal_rate, f.one_hr_max, f.dose_due, f.dose_due_unit, f.will_remainder_of_dose_be_given, f.product_amount_given, f.product_unit, f.quantity, f.ab_itemid, f.ab_name, f.dilution_text, f.dilution_comparison, f.dilution_value, f.interpretation, lag(f.drug_type) OVER (PARTITION BY f.subject_id ORDER BY c.charttime) AS previous_drug_type FROM patients p JOIN admissions a ON p.subject_id = a.subject_id JOIN chartevents c ON a.subject_id = c.subject_id AND a.hadm_id = c.hadm_id JOIN diagnoses_icd d ON c.itemid = d.icd_code AND c.charttime BETWEEN d.diag_start_date AND d.diag_end_date JOIN prescriptions r ON p.subject_id = r.subject_id AND a.hadm_id = r.hadm_id AND c.charttime BETWEEN r.starttime AND r.stoptime;